// FUNCTION: ROBLOX 0x0065ff20
void ArrowPanel::init(
	Adorn* adorn,
	const std::string& image,
	const std::string& forward,
	const std::string& backward,
	const std::string& left,
	const std::string& right,
	SDLKey forwardKey,
	SDLKey backwardKey,
	SDLKey leftKey,
